pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this) && actor != address(0));
        vm.assume(newOwner != address(0));
        // Record admin to check actor is not admin
        address admin = c.owner(); // constructor sets owner = msg.sender (admin)
        vm.assume(actor != admin);
        vm.prank(actor);
        c.setOwner(newOwner);
        // After a non-admin call, owner must remain unchanged (initial admin)
        assertTrue(c.owner() == admin);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // Record original owner before the call
        address originalOwner = c.owner();
        // Prank as a non-admin caller (any address except admin is valid; admin is msg.sender of setUp)
        vm.prank(caller);
        // Call setOwner, ignore revert outcome by low-level call to prevent test revert
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        // After the call, owner must equal originalOwner unless caller is the admin
        if (caller != address(this)) {
            assertTrue(c.owner() == originalOwner, "Non-admin caller changed owner");
        } else {
            assertTrue(c.owner() == newOwner || c.owner() == originalOwner, "Admin caller result invalid");
        }
    }
}

