pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        vm.prank(actor);
        try c.setOwner(actor) returns (bool) {
            // In the correct contract, a non-admin call should revert.
            // In the buggy contract, it succeeds, so the try/catch reports true.
            // The property is: non-admin calls must always revert.
            assertTrue(false, "Non-admin call succeeded, should have reverted");
        } catch {}
    }
}

