pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner, address adminActor) public {
        vm.assume(adminActor != address(0));
        vm.assume(_owner != address(0));
        vm.assume(adminActor != _owner);
        // The original deployer is the admin. For the fuzzed adminActor to call setOwner,
        // we need to prank as the original admin (msg.sender of setUp).
        // The constructor sets admin = msg.sender of setUp, which is this test contract.
        // To satisfy onlyAdmin, we prank as the test contract address.
        vm.prank(address(this));
        c.setOwner(_owner);
        // General rule: after setOwner(_owner) called by admin, owner must be _owner.
        // The mutant sets owner = msg.sender (admin) instead, violating the rule.
        assertTrue(c.owner() == _owner);
    }
}

