// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Keep the input space wide; no vm.assume restrictions needed besides non-zero address difference
        vm.assume(caller != c.owner());
        vm.assume(newOwner != c.owner());
        address originalOwner = c.owner();
        vm.prank(caller);
        try c.setOwner(newOwner) { } catch { }
        // After the call, if the caller is not the admin, the owner must remain unchanged.
        // Since we cannot read admin directly (it's private), we rely on the fact that in setUp,
        // the admin is msg.sender of the constructor (this test contract). A fuzzed caller is never
        // the admin unless it equals address(this), which is extremely unlikely but we can explicitly
        // allow it: if caller is the test contract itself, it IS the admin and owner change is allowed.
        bool callerIsAdmin = (caller == address(this));
        if (callerIsAdmin) {
            // admin can change owner
            assertTrue(c.owner() == newOwner || c.owner() == originalOwner);
        } else {
            // non-admin must not change owner
            assertTrue(c.owner() == originalOwner);
        }
    }
}
